// Block (composition) — a progress-tracked onboarding checklist with per-step actions.
// Card owns the surface, Stack owns arrangement, and ProgressBar/Checkbox/Button own Component behavior and look.
import { useId, type Ref } from "react";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Checkbox } from "../components/Checkbox";
import { ProgressBar } from "../components/ProgressBar";
import { Stack } from "../layouts/Stack";
import "./OnboardingChecklist.css";

export interface OnboardingChecklistProps {
  steps: {
    id: string;
    label: string;
    description?: string;
    done?: boolean;
    actionLabel?: string;
  }[];
  onStepAction?: (id: string) => void;
  heading?: string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function OnboardingChecklist({
  steps,
  onStepAction,
  heading = "Get started",
  className,
  ref,
}: OnboardingChecklistProps) {
  const headingId = useId();
  const completed = steps.filter((step) => step.done).length;
  const progress = steps.length > 0 ? (completed / steps.length) * 100 : 0;

  return (
    <Card
      ref={ref}
      role="region"
      aria-labelledby={headingId}
      className={className ? `sd-onboardingchecklist ${className}` : "sd-onboardingchecklist"}
    >
      <Stack gap={{ small: "large", medium: "medium" }} className="sd-onboardingchecklist__body">
        <>
          <h2 id={headingId} className="sd-onboardingchecklist__heading sd-type-title-medium">{heading}</h2>
        </>
        {/* "3 of 5 complete" is the bar's VALUE, not its name — so it goes to `valueLabel`, which
            drives both the visible value and `aria-valuetext`. Putting it in `label` made the
            visible text a label the accessible name ("Onboarding progress") did not contain. The
            card's own heading already names this region, so the bar stays visually label-less. */}
        {/* The value ends a line on the Card's surface, so it takes the end inset (rule 8). The bar
            has no surface of its own to justify the inset inside ProgressBar, so the Block applies
            it; the track is a line, not a box, and moves with it. */}
        <>
          <ProgressBar
            value={progress}
            showValue
            aria-label="Onboarding progress"
            valueLabel={`${completed} of ${steps.length} complete`}
          />
        </>
        <Stack gap={{ small: "large", medium: "medium" }} className="sd-onboardingchecklist__steps">
          {steps.map((step) => (
            <Stack
              key={step.id}
              direction={{ small: "column", medium: "row" }}
              align={{ small: "stretch", medium: "center" }}
              justify="between"
              gap="small"
              className="sd-onboardingchecklist__step"
            >
              {/* The step's helper line is the Checkbox's own description slot, so it becomes the
                  box's aria-describedby and takes the Checkbox's own description styling, which a
                  sibling <p> did neither of. */}
              <div className="sd-onboardingchecklist__content">
                <Checkbox isSelected={Boolean(step.done)} isReadOnly description={step.description}>
                  {step.label}
                </Checkbox>
              </div>
              {!step.done && step.actionLabel && (
                <Button
                  variant="secondary"
                  size="small"
                  className="sd-onboardingchecklist__action"
                  onPress={() => onStepAction?.(step.id)}
                >
                  {step.actionLabel}
                </Button>
              )}
            </Stack>
          ))}
        </Stack>
      </Stack>
    </Card>
  );
}

.sd-onboardingchecklist,
.sd-onboardingchecklist__content {
  width: 100%;
}

.sd-onboardingchecklist__heading {
  margin: 0;
}

/* The action must not shrink. `__content` is `width: 100%`, so from the `medium` rung up — where
   the step becomes a row — the pair is over-wide by the button's own size and flex takes the
   shortfall out of both: at 1024 the button loses 10px and its label wraps onto two lines beside
   300px of empty card. */
.sd-onboardingchecklist__action {
  flex-shrink: 0;
}
